const listCyclesAwaitingRelease = `-- name: ListCyclesAwaitingRelease :many
SELECT cycle_id, tenant_id, machine, load_number, program, parameters, source, result, released, released_by, released_at, release_note, started_at, ended_at, started_by, version FROM sterile.cycle
WHERE tenant_id = $1 AND NOT released AND result = 'passed'
ORDER BY ended_at
LIMIT $2
`

type ListCyclesAwaitingReleaseParams struct {
	TenantID uuid.UUID
	RowLimit int32
}

// The loads that have finished and not been cleared (SRS-CSSD-007).
func (q *Queries) ListCyclesAwaitingRelease(ctx context.Context, arg ListCyclesAwaitingReleaseParams) ([]SterileCycle, error) {
	rows, err := q.db.Query(ctx, listCyclesAwaitingRelease, arg.TenantID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SterileCycle{}
	for rows.Next() {
		var i SterileCycle
		if err := rows.Scan(
			&i.CycleID,
			&i.TenantID,
			&i.Machine,
			&i.LoadNumber,
			&i.Program,
			&i.Parameters,
			&i.Source,
			&i.Result,
			&i.Released,
			&i.ReleasedBy,
			&i.ReleasedAt,
			&i.ReleaseNote,
			&i.StartedAt,
			&i.EndedAt,
			&i.StartedBy,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

