const supersedeTraySet = `-- name: SupersedeTraySet :execrows
UPDATE sterile.tray_set
SET superseded_at = $1
WHERE tenant_id = $2 AND set_id = $3
  AND superseded_at IS NULL
`

type SupersedeTraySetParams struct {
	SupersededAt pgtype.Timestamptz
	TenantID     uuid.UUID
	SetID        uuid.UUID
}

// Supersession is a separate statement because the one-current index forbids
// two live versions of a code: the old row has to be closed before the new one
// may exist.
func (q *Queries) SupersedeTraySet(ctx context.Context, arg SupersedeTraySetParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeTraySet, arg.SupersededAt, arg.TenantID, arg.SetID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

